import type { Cobertura, FuenteEmbebida } from "./etiquetas-fuente-registro";

// SLT-80 (D4, R1310, R1311) — Archivo, la tipografía de la marca (docs/marca.md), embebida en el
// PDF de la guía de integración por API. Mismo patrón que `etiquetas-fuente.ts`: subconjunto TTF
// en base64, con su procedencia y su cobertura al lado. Dos pesos: Regular (texto) y Bold
// (títulos y negritas). El código va en Courier estándar de jsPDF, sin embeber (D4).
//
// Procedencia:
//   fuente      : Archivo (variable, ejes wght 100-900 y wdth 62-125), de Omnibus-Type
//   origen      : https://raw.githubusercontent.com/google/fonts/6c70c829f09ea345d3590406693220ea35c6553f/ofl/archivo/Archivo%5Bwdth%2Cwght%5D.ttf
//                 (google/fonts, ofl/archivo, commit 6c70c829f09ea345d3590406693220ea35c6553f; blob git cc64253d36665a5ca0d6719cdf1e32b3de453b51)
//   licencia    : SIL Open Font License 1.1, verificada en el origen: ofl/archivo/OFL.txt
//                 («Copyright 2020 The Archivo Project Authors … licensed under the SIL Open Font
//                 License, Version 1.1») y METADATA.pb (`license: "OFL"`). El aviso de copyright y
//                 la licencia viajan DENTRO de cada subconjunto (tabla `name`, IDs 0, 13 y 14:
//                 `--name-IDs='*'`), como permite la condición 2 de la OFL.
//   sha256 (variable original completo) : 0e094a7d3c7c4c25cf1310c4b30014f1dae9332220b1c2c88f4fa996f0b05053
//   sha256 (subconjunto commiteado, assets/fuentes/Archivo-guia-regular-subset.ttf):
//     b980bacd16d71fdf2606e3efdf073ae84198edafcfd8da28e4696bd986c180d8
//   sha256 (subconjunto commiteado, assets/fuentes/Archivo-guia-bold-subset.ttf):
//     c1cac7dcc76f3f37a5162ef2ef1bcc4d24e92f6cf22239ac1e7391aa5ecc698a
//
// Cómo se regeneran (fuera del build, sin dependencias de repo; fontTools 4.63.0):
//   python -m fontTools.varLib.instancer "Archivo[wdth,wght].ttf" wght=400 wdth=100 --static --update-name-table -o Archivo-Regular.ttf
//   python -m fontTools.varLib.instancer "Archivo[wdth,wght].ttf" wght=700 wdth=100 --static --update-name-table -o Archivo-Bold.ttf
//   python -m fontTools.subset Archivo-<Peso>.ttf --unicodes="U+0020-007E,U+00A0-00FF,U+0152-0153,U+0160-0161,U+0178,U+017D-017E,U+0192,U+02C6,U+02DC,U+2013-2014,U+2018-201A,U+201C-201E,U+2020-2022,U+2026,U+2030,U+2039-203A,U+20A1,U+20AC,U+2122,U+2192,U+2212,U+2265" --output-file=assets/fuentes/Archivo-guia-<peso>-subset.ttf --no-hinting --drop-tables+=GSUB,GPOS,GDEF,FFTM,kern,gasp,STAT --name-IDs='*' --notdef-outline --recalc-bounds
//   y el base64 de cada `.ttf` se pega en `base64` (una línea por peso).
//
// Rangos: los de la etiqueta (`etiquetas-fuente.ts`: cp1252 imprimible + U+20A1 + U+20AC) más los
// caracteres que usa la guía fuera de los bloques de código, medidos sobre
// docs/ayuda/oficina/guia-integracion-api.md el 2026-11-18: → (U+2192), − (U+2212) y ≥ (U+2265).
// fontTools añade ≤ (U+2264) por su cuenta. Archivo NO tiene ∈ ☐ ⚠ ✔: la guía los cambió por texto.
//
// Si la guía empieza a usar un carácter fuera de estos rangos, el PDF NO lo borra en silencio:
// lanza `ErrorCaracterNoImprimible` (R1311) y su test se pone rojo. Se arregla regenerando el
// subconjunto con ese carácter (si Archivo lo tiene) o cambiándolo en la guía.

/**
 * Code points que cubren LOS DOS subconjuntos (tienen el mismo cmap), en rangos INCLUSIVOS.
 * Derivados del propio archivo (`codePointsCubiertos` de `tests/unit/pdf/ttf-lector.ts` lo
 * comprueba en `tests/unit/pdf/guia-api-pdf.test.ts`), no escritos a ojo.
 */
export const COBERTURA_GUIA: Cobertura = [
  [0x0020, 0x007e],
  [0x00a0, 0x00ff],
  [0x0152, 0x0153],
  [0x0160, 0x0161],
  [0x0178, 0x0178],
  [0x017d, 0x017e],
  [0x0192, 0x0192],
  [0x02c6, 0x02c6],
  [0x02dc, 0x02dc],
  [0x2013, 0x2014],
  [0x2018, 0x201a],
  [0x201c, 0x201e],
  [0x2020, 0x2022],
  [0x2026, 0x2026],
  [0x2030, 0x2030],
  [0x2039, 0x203a],
  [0x20a1, 0x20a1],
  [0x20ac, 0x20ac],
  [0x2122, 0x2122],
  [0x2192, 0x2192],
  [0x2212, 0x2212],
  [0x2264, 0x2265],
];

export const fuenteGuiaRegular: FuenteEmbebida = {
  nombre: "ArchivoGuia",
  archivoVfs: "Archivo-guia-regular.ttf",
  estilo: "normal",
  cobertura: COBERTURA_GUIA,
  base64:
    "",
};

export const fuenteGuiaBold: FuenteEmbebida = {
  nombre: "ArchivoGuia",
  archivoVfs: "Archivo-guia-bold.ttf",
  estilo: "bold",
  cobertura: COBERTURA_GUIA,
  base64:
    "",
};
